/**
 * Data shapes. Field names and scalar types come from the API's OpenAPI (core/api/schema.d.ts, generated by
 * `npm run api:types`); only the JSON columns the API leaves free-form (steps, moves, estimate history, trophy rules,
 * page settings) are refined here. Fields beyond the core ones are optional so the demo's sample data stays short.
 */
import type { components } from './api/schema';

type Api<K extends keyof components['schemas']> = components['schemas'][K];
/** `Req` keys stay required; everything else becomes optional; `Refined` keys are left out to be redefined. */
type Shape<T, Req extends keyof T, Refined extends keyof T = never> = Pick<T, Req> &
  Partial<Omit<T, Req | Refined>>;

export interface Step {
  t: string;
  done: boolean;
}
export interface EstimateChange {
  at: string;
  from: number;
  to: number;
  reason?: string | null;
}
export interface Move {
  at: string;
  from: { date: string; start: string | null };
  to: { date: string; start: string | null };
  type: string;
}

export type Task = Shape<
  Api<'TaskOut'>,
  'id' | 'title' | 'date' | 'start' | 'est' | 'done',
  'steps' | 'estHistory' | 'moves'
> & {
  steps?: Step[] | null;
  estHistory?: EstimateChange[] | null;
  moves?: Move[] | null;
};
export type Area = Shape<Api<'AreaOut'>, 'id' | 'name' | 'color' | 'sort'>;
export type HabitDef = Shape<Api<'HabitOut'>, 'id' | 'groupName' | 'name' | 'sort' | 'active'>;
export type Project = Shape<Api<'ProjectOut'>, 'id' | 'title' | 'prio' | 'sort', 'steps'> & {
  steps: Step[];
};
export type ShoppingItem = Shape<Api<'ShoppingOut'>, 'id' | 'item' | 'need' | 'stocked'>;
export type RecurringRule = Shape<Api<'RecurringOut'>, 'id' | 'title' | 'sort'>;
/* eslint-disable @typescript-eslint/no-explicit-any -- the log's from/to/extra hold whatever each change type records */
export type Change = Shape<Api<'ChangeOut'>, 'at' | 'type', 'from' | 'to' | 'extra' | 'id'> & {
  id?: number | string;
  from?: any;
  to?: any;
  extra?: any;
};
/* eslint-enable @typescript-eslint/no-explicit-any */
export type Note = Shape<Api<'NoteOut'>, 'id' | 'at' | 'text' | 'status'>;
export type Award = Shape<Api<'AwardOut'>, 'id' | 'earnedAt'>;
export type RuntimeConfig = Api<'RuntimeConfig'>;

/** A trophy and the rule that earns it. Rules are data, so trophies can name anything without code changes. */
export interface TrophyRule {
  type:
    | 'total_wins'
    | 'habit_streak'
    | 'habit_days'
    | 'habit_week'
    | 'perfect_days'
    | 'tasks_done'
    | 'project_steps'
    | 'task_step'
    | 'moves'
    | 'estimate_changes'
    | 'sum';
  habit?: string;
  titleMatch?: string;
  area?: string;
  project?: string;
  step?: number;
  withField?: string;
  moveType?: string;
  of?: TrophyRule[];
}
export type TrophyDef = Shape<
  Api<'TrophyOut'>,
  'id' | 'name' | 'desc' | 'goal' | 'sort',
  'rule'
> & { rule: TrophyRule };

/** Key/value page settings (meal times, evening card, capacity, wording). Free-form JSON in the API. */
export interface Settings {
  appTitle?: string;
  headline?: [string, string];
  capacity?: {
    weekdayMinutes: number;
    weekendMinutes: number;
    weekdayStart: string;
    weekendStart: string;
  };
  boundary?: { time: string; label: string; sub?: string };
  workday?: { label: string; start: string; hours: number; area?: string; sub?: string };
  meals?: { time: string; text: string; highlight?: boolean }[];
  evening?: {
    eyebrow: string;
    title: string;
    text: string;
    options: { label: string; msg: string }[];
    suffix?: string;
  };
  taxCheer?: { match: string; msg: string };
  [key: string]: unknown;
}

export interface Bootstrap {
  settings: Settings;
  areas: Area[];
  habits: HabitDef[];
  habitDays: Record<string, Record<string, boolean>>;
  tasks: Task[];
  projects: Project[];
  shopping: ShoppingItem[];
  recurring: RecurringRule[];
  trophies: TrophyDef[];
  awards: Record<string, Award>;
  changes: Change[];
  notes: Note[];
}
